Method.Source:
// <summary>
/// update parm job status contain errors.
/// </summary>
void  updateParmJobStatusContainErrors()
{
    next updateParmJobStatusContainErrors();
    //CBNF019_Observability

    if (this.RecId != 0 && this.ParmJobStatus == ParmJobStatus::ContainErrors && this.PurchId != '')
    {
        DocumentStatus documentStatus = this.Ordering;

        switch (documentStatus)
        {
            case DocumentStatus::PurchaseOrder:
                METTelemetryPOConfirmationErrorEvent::runTelemetryEvent(this.PurchId, this.Log);
                break;

            case DocumentStatus::PackingSlip:
                METTelemetryPOReceiptErrorEvent::runTelemetryEvent(this.PurchId, this.Log);
                break;

            case DocumentStatus::Invoice:
                METTelemetryPOInvoiceErrorEvent::runTelemetryEvent(this.PurchId, this.Log);
                break;
        }
    }
    //CBNF019_Observability
}
